export const getStartAttemptUrl = (assessmentId: string,) => {




  return `/api/v1/learn/assessments/${assessmentId}/attempts`
}

/**
 * @summary Start Attempt
 */
export const start_attempt = async (assessmentId: string,
    startAttemptIn: StartAttemptIn, options?: Parameters<typeof httpClient>[1]): Promise<unknown> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Array.isArray(h)) return Object.fromEntries(h);
    return h;
  };
return httpClient<unknown>(getStartAttemptUrl(assessmentId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(startAttemptIn)
  }
);}





export const getStartAttemptMutationOptions = <TError = HTTPValidationError,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof start_attempt>>, TError,StartAttemptMutationVariables, TContext>, request?: SecondParameter<typeof httpClient>}
): UseMutationOptions<Awaited<ReturnType<typeof start_attempt>>, TError,StartAttemptMutationVariables, TContext> => {

const mutationKey = ['startAttempt'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof start_attempt>>, StartAttemptMutationVariables> = (props) => {
          const {assessmentId,data} = props ?? {};

          return  start_attempt(assessmentId,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type StartAttemptMutationResult = NonNullable<Awaited<ReturnType<typeof start_attempt>>>
    export type StartAttemptMutationBody = StartAttemptIn
    export type StartAttemptMutationError = HTTPValidationError
    export type StartAttemptMutationVariables = {assessmentId: string;data: StartAttemptIn}

    /**
 * @summary Start Attempt
 */
export const useStartAttempt = <TError = HTTPValidationError,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof start_attempt>>, TError,StartAttemptMutationVariables, TContext>, request?: SecondParameter<typeof httpClient>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof start_attempt>>,
        TError,
        StartAttemptMutationVariables,
        TContext
      > => {
      return useMutation(getStartAttemptMutationOptions(options), queryClient);
    }
